bool PreferencesFilePaths_script_directories_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    PreferencesFilePaths_script_directories_begin(&iter, ptr);

    if (iter.valid) {
        ListBaseIterator *internal = &iter.internal.listbase;
        if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_listbase_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            while (index-- > 0 && internal->link) {
                internal->link = internal->link->next;
            }
            found = (index == -1 && internal->link);
        }
        if (found) { *r_ptr = PreferencesFilePaths_script_directories_get(&iter); }
    }

    PreferencesFilePaths_script_directories_end(&iter);

    return found;
}

int ScriptDirectory_name_length(PointerRNA *);
void ScriptDirectory_name_get(PointerRNA *, char *);

bool PreferencesFilePaths_script_directories_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;
    char namebuf[1024];
    char *name;

    PreferencesFilePaths_script_directories_begin(&iter, ptr);

    while (iter.valid) {
        if (iter.ptr.data) {
            int namelen = ScriptDirectory_name_length(&iter.ptr);
            if (namelen < 1024) {
                ScriptDirectory_name_get(&iter.ptr, namebuf);
                if (strcmp(namebuf, key) == 0) {
                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
            }
            else {
                name = MEM_new_array_uninitialized<char>(size_t(namelen) + 1,
                                               "name string");
                ScriptDirectory_name_get(&iter.ptr, name);
                if (strcmp(name, key) == 0) {
                    MEM_delete(name);

                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
                else {
                    MEM_delete(name);
                }
            }
        }
        PreferencesFilePaths_script_directories_next(&iter);
    }
    PreferencesFilePaths_script_directories_end(&iter);

    return found;
}

