void StudioLight_solid_lights_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_StudioLight_solid_lights;

    PropCollectionBeginFunc fn = rna_UserDef_studiolight_solid_lights_begin;
    fn(iter, ptr);

    if (iter->valid) {
        iter->ptr = StudioLight_solid_lights_get(iter);
    }
}

void StudioLight_solid_lights_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_iterator_array_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = StudioLight_solid_lights_get(iter);
    }
}

void StudioLight_solid_lights_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_array_end;
    fn(iter);
}

bool StudioLight_solid_lights_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    StudioLight_solid_lights_begin(&iter, ptr);

    if (iter.valid) {
        ArrayIterator *internal = &iter.internal.array;
        if (index < 0 || index >= internal->length) {
#ifdef __GNUC__
            printf("Array iterator out of range: %s (index %d)\n", __func__, index);
#else
            printf("Array iterator out of range: (index %d)\n", index);
#endif
        }
        else if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_array_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            internal->ptr += internal->itemsize * index;
            found = 1;
        }
        if (found) { *r_ptr = StudioLight_solid_lights_get(&iter); }
    }

    StudioLight_solid_lights_end(&iter);

    return found;
}

